\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome5}
\pagestyle{empty}

% ── Dark Data-Dashboard Color Theme ──
\definecolor{primary}{HTML}{0F172A}      % deep navy (title bar)
\definecolor{secondary}{HTML}{38BDF8}    % electric blue
\definecolor{accent}{HTML}{34D399}       % bright green
\definecolor{bgposter}{HTML}{0B1120}     % poster background
\definecolor{cardbg}{HTML}{151E32}       % card background
\definecolor{cardbg2}{HTML}{1E293B}      % alt card background
\definecolor{cardbg3}{HTML}{172033}      % alt card background
\definecolor{textlight}{HTML}{E2E8F0}    % main text
\definecolor{textmuted}{HTML}{94A3B8}    % muted text
\definecolor{stathighlight}{HTML}{1E293B}
\definecolor{greenbg}{HTML}{064E3B}      % green tint for positive
\definecolor{bluebg}{HTML}{0C4A6E}       % blue tint
\definecolor{purplebg}{HTML}{3B0764}     % purple tint
\definecolor{roweven}{HTML}{1E293B}
\definecolor{rowodd}{HTML}{151E32}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[4mm]
  {\fontsize{28}{34}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe, dark theme) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbg2,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25},
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg2,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25},
  },
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg2,
    borderline west={6pt}{0pt}{textmuted},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={textmuted!40},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=greenbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25},
  },
  statcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    left=14pt, right=14pt, top=10pt, bottom=10pt,
    valign=center, halign=center,
    drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=4mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{90}{108}\selectfont\bfseries\color{white} Open Source Contributor Index}\\[14pt]
  {\fontsize{44}{54}\selectfont\color{secondary} March 2026}\\[10pt]
  {\fontsize{32}{40}\selectfont\color{textmuted} A monthly ranking of commercial organizations by employees' GitHub contributions}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{tcolorbox}[statcard, colback=cardbg]
      {\fontsize{72}{88}\selectfont\bfseries\color{accent} 548}\\[6pt]
      {\fontsize{30}{36}\selectfont\color{textmuted} Google Active Contributors}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{accent} $\uparrow$ +128 MoM}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{tcolorbox}[statcard, colback=cardbg]
      {\fontsize{72}{88}\selectfont\bfseries\color{secondary} 2,721}\\[6pt]
      {\fontsize{30}{36}\selectfont\color{textmuted} Top 10 Combined Active}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{accent} $\uparrow$ +595 MoM}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{tcolorbox}[statcard, colback=cardbg]
      {\fontsize{72}{88}\selectfont\bfseries\color{secondary} 239}\\[6pt]
      {\fontsize{30}{36}\selectfont\color{textmuted} Organizations Tracked}\\[4pt]
      {\fontsize{28}{34}\selectfont\color{accent} Python leads at 20.3\%}
    \end{tcolorbox}
  \end{minipage}
}

% ══ COLUMN 1 ══

% Top 10 Leaderboard (rows 6-14, the centerpiece)
\posterbox[bluecard, title={\faIcon{list-ol}\hspace{8pt}Top 10 Contributing Organizations}
]{name=leaderboard, column=1, span=2, between=row6 and row14}{
  \fontsize{28}{36}\selectfont
  \renewcommand{\arraystretch}{1.7}
  \begin{tabular}{@{}c l r r r@{}}
    \textbf{\color{secondary}\#} & \textbf{\color{secondary}Organization} & \textbf{\color{secondary}Active} & \textbf{\color{secondary}MoM} & \textbf{\color{secondary}Total} \\
    & & \textbf{\color{secondary}Contr.} & \textbf{\color{secondary}Change} & \textbf{\color{secondary}Comm.} \\
    \hline
    \rowcolor{roweven}
    {\color{accent}\bfseries 1} & {\color{white}\bfseries Google} & {\color{white}\bfseries 548} & {\color{accent}\bfseries +128} & {\color{white}\bfseries 1,986} \\
    \rowcolor{rowodd}
    {\color{secondary}\bfseries 2} & Microsoft & 438 & {\color{accent}+74} & 1,189 \\
    \rowcolor{roweven}
    {\color{secondary}\bfseries 3} & Red Hat & 432 & {\color{accent}+94} & 1,378 \\
    \rowcolor{rowodd}
    {\color{secondary}\bfseries 4} & AMD & 233 & {\color{accent}+66} & 627 \\
    \rowcolor{roweven}
    {\color{secondary}\bfseries 5} & Datadog & 221 & {\color{accent}+34} & 411 \\
    \rowcolor{rowodd}
    {\color{secondary}\bfseries 6} & Intel & 217 & {\color{accent}+48} & 707 \\
    \rowcolor{roweven}
    {\color{secondary}\bfseries 7} & NVIDIA & 194 & {\color{accent}+41} & 650 \\
    \rowcolor{rowodd}
    {\color{secondary}\bfseries 8} & SUSE & 158 & {\color{accent}+32} & 353 \\
    \rowcolor{roweven}
    {\color{secondary}\bfseries 9} & IBM & 140 & {\color{accent}+44} & 616 \\
    \rowcolor{rowodd}
    {\color{secondary}\bfseries 10} & SAP & 140 & {\color{accent}+34} & 378 \\
  \end{tabular}
  \vspace{8pt}
  {\fontsize{26}{32}\selectfont\color{textmuted} All top 10 organizations showed positive MoM growth in both active contributors and total community.}
}

% Growth Momentum Chart (col 3, rows 6-11)
\posterbox[greencard, title={\faIcon{chart-line}\hspace{8pt}Monthly Growth Momentum}
]{name=growth, column=3, between=row6 and row11}{
  \posterfig{0.98}{figures/growth_chart.png}{MoM increase in active contributors (Feb to Mar 2026)}
  \vspace{4pt}
  {\fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Google added the most: {\color{accent}\bfseries +128} active contributors
    \item IBM showed strongest relative growth: {\color{accent}\bfseries +44} (46\% increase)
    \item Combined monthly increase: {\color{accent}\bfseries +595} active contributors
  \end{itemize}
  }
}

% Language Distribution Chart (col 3, rows 11-14)
\posterbox[bluecard, title={\faIcon{code}\hspace{8pt}Programming Languages}
]{name=languages, column=3, between=row11 and row14}{
  \posterfig{0.98}{figures/languages_chart.png}{Share of programming languages across tracked contributions}
}

% ══ ROW B (rows 14-18) ══

% Ecosystem Scale (col 1)
\posterbox[darkcard, title={\faIcon{globe}\hspace{8pt}Ecosystem Scale}
]{name=scale, column=1, between=row14 and row18}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item {\color{secondary}\bfseries 239} organizations tracked globally
    \item Nearly {\color{secondary}\bfseries 2,000} contributors in Google's community alone
    \item Top 3 hold {\color{accent}\bfseries 1,418} active contributors combined
    \item Every top-10 org posted positive MoM growth
  \end{itemize}
  \vspace{10pt}
  {\fontsize{28}{36}\selectfont\color{textmuted} OSCI is licensed under GPL v3.0, ensuring transparent criteria and community-driven improvement.}
}

% License Usage (col 2)
\posterbox[greencard, title={\faIcon{file-contract}\hspace{8pt}License Landscape}
]{name=licenses, column=2, between=row14 and row18}{
  \fontsize{32}{42}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item {\color{accent}\bfseries Apache-2.0} --- most prevalent license
    \item {\color{secondary}\bfseries MIT} --- permissive, widely adopted
    \item {\color{secondary}\bfseries GPL-2.0} --- copyleft stronghold
    \item {\color{textmuted} Other} --- various permissive / copyleft
  \end{enumerate}
  \vspace{10pt}
  {\fontsize{28}{36}\selectfont\color{textmuted} Enterprise-friendly permissive licensing enables broad commercial adoption.}
}

% Key Takeaways (col 3)
\posterbox[highlightcard, title={\faIcon{lightbulb}\hspace{8pt}Key Takeaways}
]{name=takeaways, column=3, between=row14 and row18}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item {\color{accent}\bfseries Google dominates} with 548 active contributors
    \item {\color{accent}\bfseries Ecosystem accelerating} --- +595 combined MoM
    \item {\color{accent}\bfseries Python leads} at 20.3\% of all contributions
    \item {\color{accent}\bfseries Permissive licenses} (Apache-2.0, MIT) rule
  \end{itemize}
}

% ══ FOOTER ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
]{name=footer, column=1, span=3, between=row18 and bottom}{
  {\fontsize{28}{36}\selectfont\color{textmuted} Data: Open Source Contributor Index (OSCI) \quad|\quad March 2026 Report \quad|\quad \color{secondary}\faIcon{github}\hspace{4pt}github.com/epam/OSCI}
}

\end{tcbposter}
\end{document}
